library(ggplot2)

plot_maxi&lt;- function(data= max_i){
  heatmap_plot &lt;- max_i

  heatmap_plot &lt;- ggplot(data = max_i, aes(x = b_out, y = g_out, fill= maxi_out)) + 
    geom_tile() #scatter plot, data defined, x and y labels

  return(heatmap_plot)

}

plot_maxi() #print the heat map
